  if (!user) {
    return null;
  }

  const isStaff = user?.role === 'pharmacist' || user?.role === 'admin';

  return (
    <div className="min-h-screen bg-background">
      {isStaff ? <StaffDashboard user={user!} /> : <PatientDashboard user={user!} />}
    </div>
