                      required={!isLogin}
                      data-testid="input-firstName"
                    />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="lastName" className="text-gray-700">Last Name</Label>
                    <Input
                      id="lastName"
                      type="text"
                      value={lastName}
                      onChange={(e) => setLastName(e.target.value)}
                      placeholder="Doe"
                      required={!isLogin}
                      data-testid="input-lastName"
                    />
                  </div>
                </div>
              )}

              <div className="space-y-2">
                <Label htmlFor="email" className="text-gray-700">Email Address</Label>
                <Input
                  id="email"
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="john@example.com"
                  required
                  data-testid="input-email"
                />
              </div>

              {!isLogin && (
                <div className="space-y-2">
                  <Label htmlFor="phoneNumber" className="text-gray-700">Phone Number (Optional)</Label>
                  <Input
                    id="phoneNumber"
                    type="tel"
                    value={phoneNumber}
                    onChange={(e) => setPhoneNumber(e.target.value)}
                    placeholder="+254 700 000 000"
                    data-testid="input-phoneNumber"
                  />
                </div>
              )}

              <div className="space-y-2">
                <Label htmlFor="password" className="text-gray-700">Password</Label>
                <div className="relative">
                  <Input
                    id="password"
                    type={showPassword ? "text" : "password"}
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    placeholder="Enter your password"
                    required
                    data-testid="input-password"
                  />
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    className="absolute right-0 top-0 h-full px-3 py-2 hover:bg-transparent"
                    onClick={() => setShowPassword(!showPassword)}
                    data-testid="button-toggle-password"
                  >
                    {showPassword ? (
                      <EyeOff className="h-4 w-4" />
                    ) : (
                      <Eye className="h-4 w-4" />
                    )}
                  </Button>
                </div>
                {!isLogin && (
                  <p className="text-xs text-gray-500">
                    Must be at least 6 characters long
                  </p>
                )}
              </div>

              <Button 
                type="submit"
                className="w-full bg-green-600 hover:bg-green-700 text-white py-3 text-lg font-semibold"
                disabled={loginMutation.isPending || signupMutation.isPending}
                data-testid="button-submit"
              >
                <Shield className="h-5 w-5 mr-2" />
                {(loginMutation.isPending || signupMutation.isPending) 
                  ? "Please wait..." 
                  : (isLogin ? "Sign In Securely" : "Create Account")}
              </Button>
            </form>

            <Separator />

            <div className="text-center space-y-3">
              <Button
                type="button"
                variant="ghost"
                onClick={() => setIsLogin(!isLogin)}
                className="text-green-600 hover:text-green-700 font-semibold"
                data-testid="button-toggle-form"
              >
                {isLogin 
                  ? "Don't have an account? Create Account" 
                  : "Already have an account? Sign In"}
              </Button>

              {/* Forgot Password Dialog */}
              {isLogin && (
                <Dialog open={showForgotPassword} onOpenChange={setShowForgotPassword}>
                  <DialogTrigger asChild>
                    <Button
                      type="button"
                      variant="link"
                      className="text-sm text-gray-600 hover:text-gray-800 p-0 h-auto"
                      data-testid="button-forgot-password"
                    >
                      Forgot your password?
                    </Button>
                  </DialogTrigger>
                  <DialogContent className="sm:max-w-md">
                    <DialogHeader>
                      <DialogTitle className="flex items-center space-x-2">
                        <Mail className="h-5 w-5 text-green-600" />
                        <span>Reset Password</span>
                      </DialogTitle>
                      <DialogDescription>
                        Enter your email address and we'll send you a link to reset your password.
                      </DialogDescription>
                    </DialogHeader>

                    <form onSubmit={handleForgotPassword} className="space-y-4">
                      <div className="space-y-2">
                        <Label htmlFor="forgotEmail">Email Address</Label>
                        <Input
                          id="forgotEmail"
                          type="email"
                          value={forgotPasswordEmail}
                          onChange={(e) => setForgotPasswordEmail(e.target.value)}
                          placeholder="Enter your email address"
                          required
                          data-testid="input-forgot-email"
                        />
                      </div>

                      <div className="flex justify-end space-x-2">
                        <Button
                          type="button"
                          variant="outline"
                          onClick={() => setShowForgotPassword(false)}
                          data-testid="button-cancel-forgot"
                        >
                          Cancel
                        </Button>
                        <Button
                          type="submit"
                          disabled={forgotPasswordMutation.isPending}
                          data-testid="button-send-reset"
                        >
                          <Mail className="h-4 w-4 mr-2" />
                          {forgotPasswordMutation.isPending ? "Sending..." : "Send Reset Link"}
                        </Button>
                      </div>
                    </form>
                  </DialogContent>
                </Dialog>
              )}
            </div>

            {/* Features - Only show on login */}
            {isLogin && (
              <div className="space-y-3">
                <h4 className="text-sm font-medium text-gray-900">What you can do:</h4>
                <div className="grid grid-cols-1 gap-2 text-xs text-gray-600">
                  <div className="flex items-center space-x-2">
                    <div className="w-2 h-2 bg-green-500 rounded-full"></div>
                    <span>Upload and manage prescriptions</span>
                  </div>
                  <div className="flex items-center space-x-2">
                    <div className="w-2 h-2 bg-green-500 rounded-full"></div>
                    <span>Track your orders in real-time</span>
                  </div>
                  <div className="flex items-center space-x-2">
                    <div className="w-2 h-2 bg-green-500 rounded-full"></div>
                    <span>Book online consultations</span>
                  </div>
                  <div className="flex items-center space-x-2">
                    <div className="w-2 h-2 bg-green-500 rounded-full"></div>
                    <span>Access your medical history</span>
                  </div>
                </div>
              </div>
            )}

            <Separator />

            {/* Navigation Links */}
            <div className="space-y-3">
              <div className="text-center">
                <span className="text-sm text-gray-600">Staff member? </span>
                <Button
                  onClick={handleAdminLogin}
                  variant="link"
                  className="text-red-600 hover:text-red-700 p-0 h-auto font-semibold"
                  data-testid="link-admin-login"
                >
                  Staff Portal
                </Button>
              </div>

              <div className="text-center">
                <Link href="/">
                  <Button 
                    variant="ghost" 
                    className="text-gray-600 hover:text-gray-800"
                    data-testid="link-back-to-homepage"
                  >
                    <ArrowLeft className="h-4 w-4 mr-2" />
                    Back to Homepage
                  </Button>
                </Link>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

